def _json(h,status,payload):
    body=json.dumps(payload,ensure_ascii=False,default=str).encode(); h.send_response(status); h.send_header("Content-Type","application/json; charset=utf-8"); h.send_header("Cache-Control","no-store"); h.send_header("Content-Length",str(len(body))); h.end_headers(); h.wfile.write(body)

def _html(h,status,body):
    body=body.encode("utf-8"); h.send_response(status); h.send_header("Content-Type","text/html; charset=utf-8"); h.send_header("Cache-Control","no-store"); h.send_header("Content-Length",str(len(body))); h.end_headers(); h.wfile.write(body)

